#include <string>

class Solution {
public:
    bool validDigitNumber(int n, int x) {
        std::string s = std::to_string(n);
        char target = '0' + x;
        if (s[0] == target) return false;
        return s.find(target) != std::string::npos;
    }
};

class Solution {
    public boolean validDigitNumber(int n, int x) {
        String s = Integer.toString(n);
        char target = (char)('0' + x);
        if (s.charAt(0) == target) return false;
        return s.indexOf(target) != -1;
    }
}

function validDigitNumber(n, x) {
    const s = n.toString();
    const target = x.toString();
    if (s[0] === target) return false;
    return s.includes(target);
}
